// Separa el texto para el estudiante del bloque de acciones propuestas.
// Acepta ```acciones ... ``` (formato actual) y <acciones>...</acciones>.
const item = $input.first().json || {};
let salida = String(item.output || item.text || '');
let acciones = [];
const patrones = [/```acciones\s*([\s\S]*?)```/, /<acciones>([\s\S]*?)<\/acciones>/];
for (const re of patrones) {
  const m = salida.match(re);
  if (!m) continue;
  try {
    const parsed = JSON.parse(m[1].trim());
    acciones = Array.isArray(parsed) ? parsed : (Array.isArray(parsed.acciones) ? parsed.acciones : [parsed]);
  } catch (e) { acciones = []; }
  salida = salida.replace(m[0], '');
}
const texto = salida.trim();
// "respuesta" se conserva por compatibilidad con la versión anterior del flujo.
return [{ json: { texto, respuesta: texto, acciones } }];
